//! Strata as the plan splits them: the static part of every stratum in
//! evaluation order, then the non-static part of each. A part is
//! generated by [`non_recursive`] or [`recursive`]: its prelude, the
//! planned rule bodies that run outside any loop, then its heads or its
//! loop. The rules' pieces come from [`rule`](crate::rule); a relation
//! binds the union of its parts, merged by its lattice column when it has
//! one.

mod non_recursive;
mod recursive;

use std::mem;

use flowlog_planner::planner::StratumPlanner;
use flowlog_planner::planner::Transformation;
use flowlog_profiler::PlanGraph;
use flowlog_profiler::with_plan_graph;
use proc_macro2::TokenStream;
use quote::quote;
use tracing::trace;

use crate::Codegen;
use crate::CodegenError;

impl Codegen {
    /// Returns the static part of every stratum of the plan, one fragment
    /// each, in evaluation order. A static step reads only static
    /// collections, so the fragments read nothing non-static.
    pub(crate) fn gen_static_strata(
        &mut self,
        strata: &[StratumPlanner],
        plan_graph: &mut Option<PlanGraph>,
    ) -> Result<Vec<TokenStream>, CodegenError> {
        let mut flows = Vec::with_capacity(strata.len());
        let evaluation_order = strata.iter().enumerate();
        for (idx, stratum) in evaluation_order {
            with_plan_graph(plan_graph, |plan_graph| {
                plan_graph.update_stratum_block(idx);
            });
            flows.push(if stratum.is_recursive() {
                self.gen_static_recursive(stratum, plan_graph)?
            } else {
                self.gen_static_non_recursive(stratum, plan_graph)?
            });
        }
        Ok(flows)
    }

    /// Returns the non-static part of every stratum of the plan, one
    /// fragment each, in evaluation order. The fragments read the static
    /// parts of every stratum, so they follow
    /// [`Self::gen_static_strata`]'s.
    pub(crate) fn gen_non_static_strata(
        &mut self,
        strata: &[StratumPlanner],
        plan_graph: &mut Option<PlanGraph>,
    ) -> Result<Vec<TokenStream>, CodegenError> {
        let mut flows = Vec::with_capacity(strata.len());
        let evaluation_order = strata.iter().enumerate();
        for (idx, stratum) in evaluation_order {
            with_plan_graph(plan_graph, |plan_graph| {
                plan_graph.update_stratum_block(idx);
            });
            flows.push(if stratum.is_recursive() {
                self.gen_non_static_recursive(stratum, plan_graph)?
            } else {
                self.gen_non_static_non_recursive(stratum, plan_graph)?
            });
        }
        Ok(flows)
    }

    /// Returns a prelude: `steps`, planned steps of `stratum` outside any
    /// loop, into the program-wide outer-scope arrangement cache
    /// (`self.outer_fp_to_arrangement`). A recursive stratum has one too
    /// when the planner factors work that reads no feedback out of its
    /// loop.
    fn gen_prelude(
        &mut self,
        stratum: &StratumPlanner,
        steps: &[Transformation],
        plan_graph: &mut Option<PlanGraph>,
    ) -> Result<Vec<TokenStream>, CodegenError> {
        // A stratum often has no step in one of its parts: skip the copy of
        // the program-wide bindings then.
        if steps.is_empty() {
            return Ok(Vec::new());
        }
        let global_fp_to_ident = self.global_fp_to_ident.clone();
        let mut outer_fp_to_arrangement = mem::take(&mut self.outer_fp_to_arrangement);
        let flows = steps
            .iter()
            .map(|transformation| {
                self.gen_operator(
                    &global_fp_to_ident,
                    transformation,
                    &mut outer_fp_to_arrangement,
                    stratum,
                    None,
                    plan_graph,
                )
            })
            .collect::<Result<Vec<_>, _>>();
        self.outer_fp_to_arrangement = outer_fp_to_arrangement;
        let flows = flows?;
        trace!("Generated prelude:\n{}\n", quote! { #(#flows)* });
        Ok(flows)
    }
}
